import cypari2, sympy
pari = cypari2.Pari()
def trial_factor(m):
    f, p = {}, 2
    while p * p <= m:
        while m % p == 0:
            f[p] = f.get(p, 0) + 1; m //= p
        p += 1
    if m > 1: f[m] = f.get(m, 0) + 1
    return f
def is_prime_td(m):
    return m >= 2 and all(m % p for p in range(2, int(m**0.5) + 1))
for n in [131, 163, 233, 283, 409, 571]:
    prime = is_prime_td(n)
    phi = n - 1 if prime else None
    fac = trial_factor(n - 1)
    # reduction: start from candidate n-1, strip each prime while 2^(e/p) == 1
    e, trace = n - 1, []
    for p in sorted(fac):
