            trace.append('strip %d: 2^%d = 1 mod %d' % (p, e // p, n)); e //= p
    efac = trial_factor(e) if e > 1 else {}
    checks = {('2^(%d/%d)=2^%d' % (e, p, e // p)): pow(2, e // p, n) for p in sorted(efac)}
    brute = next(k for k in range(1, n) if pow(2, k, n) == 1)
