import random, cypari2, flint, sympy
pari = cypari2.Pari()
deg = lambda a: a.bit_length() - 1
def pmul(a, b):
    r = 0
    while b:
        if b & 1: r ^= a
        a <<= 1; b >>= 1
    return r
def pmod(a, m):
    dm = deg(m)
    while a and deg(a) >= dm: a ^= m << (deg(a) - dm)
    return a
def pgcd(a, b):
    while b: a, b = b, pmod(a, b)
    return a
def pdiv(a, m):
    q, dm = 0, deg(m)
    while a and deg(a) >= dm:
        s = deg(a) - dm; q ^= 1 << s; a ^= m << s
    assert a == 0
    return q
def primes_of(d): return [p for p in range(2, d + 1) if d % p == 0 and all(p % q for q in range(2, p))]
def frob_iter(x, k, f):  # x^(2^k) mod f
    for _ in range(k): x = pmod(pmul(x, x), f)
    return x
def rabin(f):
    d = deg(f)
    if frob_iter(2, d, f) != pmod(2, f): return False
    return all(pgcd(f, frob_iter(2, d // p, f) ^ pmod(2, f)) == 1 for p in primes_of(d))
def edf(f, d, rng):
    if deg(f) == d: return [f]
    while True:
        g = rng.getrandbits(deg(f)) | 1
        T, h = 0, pmod(g, f)
        for _ in range(d): T ^= h; h = pmod(pmul(h, h), f)
        u = pgcd(f, T)
        if 0 < deg(u) < deg(f): return edf(u, d, rng) + edf(pdiv(f, u), d, rng)
for n in [17, 23, 31, 41]:
    phi = (1 << n) - 1; d = int(pari('znorder(Mod(2,%d))' % n))
    own = sorted(edf(phi, d, random.Random(20260925)))
    prod = 1
    for g in own: prod = pmul(prod, g)
    pf = pari('factormod(sum(i=0,%d,x^i), 2)' % (n - 1))
    par = sorted(int(pari('subst(lift(%s), x, 2)' % pf[0][i])) for i in range(len(pf[0])))
    fl = sorted(sum(int(c) << i for i, c in enumerate(g.coeffs())) for g, k in flint.nmod_poly([1] * n, 2).factor()[1])
    X = sympy.symbols('X'); _, sl = sympy.factor_list(sum(X**i for i in range(n)), modulus=2)
    sy = sorted(sum((int(c) % 2) << i for i, c in enumerate(reversed(sympy.Poly(g, X).all_coeffs()))) for g, k in sl)
    print('n=%d ord_n(2)=%d (n-1)/ord=%d count=%d degrees=%s product==Phi_n:%s all_Rabin_irreducible:%s own==PARI==FLINT==SymPy:%s' % (n, d, (n - 1) // d, len(own), sorted({deg(g) for g in own}), prod == phi, all(rabin(g) for g in own), own == par == fl == sy))
