def fac(n):
    out, d = {}, 2
    while d * d <= n:
        while n % d == 0:
            out[d] = out.get(d, 0) + 1; n //= d
        d += 1
    if n > 1: out[n] = out.get(n, 0) + 1
    return out
def divisors(n):
    ds = [1]
    for p, k in fac(n).items():
        ds = [d * p**i for d in ds for i in range(k + 1)]
    return sorted(ds)
